// Author: MiYu. Source worker/mine commands, occupancy, carried gold, direct mining and resource lifetime consumers.
#include "session.h"
#include "setup.h"
#include <bit>
#include <iostream>
#include <algorithm>

using namespace war3;
int wmain(int argc,wchar_t** argv) {
    try {
        if(argc!=3)throw std::runtime_error("Usage: war3_harvest_tests <data-root> <generated-map>");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto check=[](bool value,const char* message){if(!value)throw std::runtime_error(message);};auto real=[](float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));};float x=std::bit_cast<float>(vm.invoke("GetStartLocationX",std::array{vm.integer(0)}).bits),y=std::bit_cast<float>(vm.invoke("GetStartLocationY",std::array{vm.integer(0)}).bits);auto spawn=[&](const char* type,unsigned owner,float dx){return vm.invoke("CreateUnit",std::array{vm.handle("player",0x100000+owner),vm.integer(std::bit_cast<std::int32_t>(ObjectData::code(type))),vm.real(real(x+dx)),vm.real(real(y)),vm.real(real(270))});};auto resource=[&](jass::Value mine,int amount){vm.invoke("SetResourceAmount",std::array{mine,vm.integer(amount)});};auto state=[&](unsigned owner,unsigned key){auto& values=session.config().players[owner].states;auto it=values.find(key);return it==values.end()?0:it->second;};
        for(unsigned owner=0;owner<3;++owner)for(unsigned other=0;other<3;++other)if(owner!=other)vm.invoke("SetPlayerAlliance",std::array{vm.handle("player",0x100000+owner),vm.handle("player",0x100000+other),vm.handle("alliancetype",0),vm.boolean(true)});auto mine=spawn("ngol",15,0),worker=spawn("hpea",0,32);spawn("htow",0,64);resource(mine,25);check(session.harvest(worker.bits,mine.bits),"Normal mine command rejected");session.advance(1.03125);check(session.units().at(worker.bits)->carriedGold==10 && !session.units().at(worker.bits)->gather.inside && state(0,1)==0,"Mine did not produce carried gold before deposit");check(session.stopUnit(worker.bits) && session.units().at(worker.bits)->carriedGold==10,"Stop discarded carried gold");auto buttons=session.commands(worker.bits,0);check(std::any_of(buttons.begin(),buttons.end(),[](auto& b){return b.action==CommandAction::ReturnResources;}),"Carried gold did not change command button");check(vm.invoke("IssueImmediateOrder",std::array{worker,vm.string("returnresources")}).bits!=0,"Return command rejected");session.advance(.03125);check(state(0,1)==10 && state(0,15)==10 && session.units().at(worker.bits)->carriedGold==0,"Deposit did not update current/cumulative resource states");check(session.harvest(worker.bits,mine.bits),"Repeated harvest rejected");session.advance(3);check(session.units().at(mine.bits)->resources==0 && std::bit_cast<float>(session.units().at(mine.bits)->life.bits())==0 && state(0,1)==25,"Finite mine depletion or final partial load differs");
        auto haunted=spawn("ugol",1,0),acolyte=spawn("uaco",1,32);resource(haunted,30);check(session.harvest(acolyte.bits,haunted.bits),"Acolyte mine command rejected");session.advance(1.03125);check(state(1,1)==2 && session.units().at(acolyte.bits)->carriedGold==0 && !session.units().at(acolyte.bits)->gather.inside,"Acolyte mine did not credit direct proportional gold");check(!session.harvest(worker.bits,haunted.bits),"Wrong worker accepted for haunted mine");
        auto entangled=spawn("egol",2,0),wisp=spawn("ewsp",2,32);resource(entangled,30);check(session.harvest(wisp.bits,entangled.bits),"Wisp mine command rejected");session.advance(.03125);check(session.units().at(wisp.bits)->gather.inside && vm.invoke("IsUnitHidden",std::array{wisp}).bits!=0,"Inside wisp still exposed as visible");vm.invoke("PauseUnit",std::array{wisp,vm.boolean(true)});session.advance(2);check(state(2,1)==0,"Paused mining advanced");vm.invoke("PauseUnit",std::array{wisp,vm.boolean(false)});session.advance(1);check(state(2,1)==2,"Resumed wisp mine did not credit gold");vm.invoke("RemoveUnit",std::array{entangled});session.advance(.03125);check(!session.units().at(wisp.bits)->gather.inside && session.units().at(wisp.bits)->gather.phase==GatherOrder::Phase::None,"Mine removal retained hidden worker");if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS harvest consumers: source mines, carried/deposited gold, commands, pause, depletion and removal\n";return 0;
    }catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
}
